-- 1: Define table variable
CREATE OR REPLACE TEMPORARY TABLE UTIL.TMP_ADF_EXPORT_COPY_CONTROL (
	ADF_COPY_CONTROL_KEY NUMBER NOT NULL, 
	INSERT_DATETIME TIMESTAMP_TZ NOT NULL, 
	LAST_UPDATED_DATETIME TIMESTAMP_TZ NOT NULL, 
	IS_ACTIVE BOOLEAN NOT NULL, 
	SOURCE_SCHEMA_NAME VARCHAR NOT NULL, 
	SOURCE_VIEW_NAME VARCHAR NOT NULL, 
	TARGET_DATA_LAKE_PATH VARCHAR NOT NULL,
    TARGET_XDRIVE_PATH VARCHAR NOT NULL,
	FILE_FORMAT VARCHAR NOT NULL,
    CUSTOMER_EMAIL_ADDRESS VARCHAR NOT NULL,
    ADF_TRIGGER_NAME VARCHAR,
	CONSTRAINT PK_ADF_COPY_CONTROL PRIMARY KEY (ADF_COPY_CONTROL_KEY),
	CONSTRAINT UK_ADF_COPY_CONTROL UNIQUE (SOURCE_SCHEMA_NAME, SOURCE_VIEW_NAME)
	)
	COMMENT = 'Control table for exporting Snowflake views';    

