-- 3: Insert any new items into the table from the table variable
INSERT INTO UTIL.ADF_EXPORT_COPY_CONTROL (ADF_COPY_CONTROL_KEY, INSERT_DATETIME, LAST_UPDATED_DATETIME, IS_ACTIVE, SOURCE_SCHEMA_NAME, SOURCE_VIEW_NAME, TARGET_DATA_LAKE_PATH, TARGET_XDRIVE_PATH, FILE_FORMAT, CUSTOMER_EMAIL_ADDRESS, ADF_TRIGGER_NAME)
SELECT TMP.ADF_COPY_CONTROL_KEY, TMP.INSERT_DATETIME, TMP.LAST_UPDATED_DATETIME, TMP.IS_ACTIVE, TMP.SOURCE_SCHEMA_NAME, TMP.SOURCE_VIEW_NAME, TMP.TARGET_DATA_LAKE_PATH, TMP.TARGET_XDRIVE_PATH, TMP.FILE_FORMAT, TMP.CUSTOMER_EMAIL_ADDRESS, TMP.ADF_TRIGGER_NAME 
FROM UTIL.TMP_ADF_EXPORT_COPY_CONTROL TMP
	LEFT JOIN UTIL.ADF_EXPORT_COPY_CONTROL TB1 ON TB1.ADF_COPY_CONTROL_KEY = TMP.ADF_COPY_CONTROL_KEY
WHERE TB1.ADF_COPY_CONTROL_KEY IS NULL;

-- 4: Update any modified values with the values from the table variables
UPDATE UTIL.ADF_EXPORT_COPY_CONTROL LIVE_TABLE
SET
LIVE_TABLE.ADF_COPY_CONTROL_KEY = TMP.ADF_COPY_CONTROL_KEY, 
LIVE_TABLE.INSERT_DATETIME = TMP.INSERT_DATETIME, 
LIVE_TABLE.LAST_UPDATED_DATETIME = TMP.LAST_UPDATED_DATETIME, 
LIVE_TABLE.IS_ACTIVE = TMP.IS_ACTIVE, 
LIVE_TABLE.SOURCE_SCHEMA_NAME = TMP.SOURCE_SCHEMA_NAME, 
LIVE_TABLE.SOURCE_VIEW_NAME = TMP.SOURCE_VIEW_NAME, 
LIVE_TABLE.TARGET_DATA_LAKE_PATH = TMP.TARGET_DATA_LAKE_PATH, 
LIVE_TABLE.TARGET_XDRIVE_PATH = TMP.TARGET_XDRIVE_PATH, 
LIVE_TABLE.FILE_FORMAT = TMP.FILE_FORMAT,
LIVE_TABLE.CUSTOMER_EMAIL_ADDRESS = TMP.CUSTOMER_EMAIL_ADDRESS, 
LIVE_TABLE.ADF_TRIGGER_NAME = TMP.ADF_TRIGGER_NAME
FROM UTIL.TMP_ADF_EXPORT_COPY_CONTROL TMP
WHERE LIVE_TABLE.ADF_COPY_CONTROL_KEY = TMP.ADF_COPY_CONTROL_KEY
;

